//! Original native identity, equality, brand and origin witnesses.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://node-equality.test/",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}
#[test]
fn node_equality_descriptors_nullable_brands_and_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var a=document.createTextNode('same'),b=document.createTextNode('same'),touched=0;
for(var name of ['isSameNode','isEqualNode']){var method=Node.prototype[name],desc=Object.getOwnPropertyDescriptor(Node.prototype,name);if(method.name!==name||method.length!==1||!desc.enumerable||!desc.writable||!desc.configurable)throw 'canonical descriptor';for(var bad of [{},null,Node.prototype]){var caught=false;try{method.call(bad,a);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'receiver brand';}var caught=false;try{method.call(a);}catch(e){caught=e instanceof TypeError;}if(!caught||method.call(a,null)||method.call(a,undefined))throw 'required nullable argument';var caught=false;try{method.call(a,{toString:function(){touched++;return a;}});}catch(e){caught=e instanceof TypeError;}if(!caught||touched)throw 'Node conversion has no author coercion';}
if(!a.isSameNode(a)||a.isSameNode(b)||!a.isEqualNode(b)||!a.isEqualNode(a))throw 'identity versus equal data';a.author=17;b.author=21;if(!a.isEqualNode(b))throw 'author fields ignored';b.data='different';if(a.isEqualNode(b))throw 'current native data';
"#);}
#[test]
fn node_equality_namespace_unordered_attributes_exact_units_and_interfaces(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var x=document.implementation.createDocument('urn:source','p:Root'),a=x.documentElement,b=x.createElementNS('urn:source','p:Root');a.setAttributeNS('urn:attr','one:Name','value');a.setAttribute('other','2');b.setAttribute('other','2');b.setAttributeNS('urn:attr','two:Name','value');if(!a.isEqualNode(b))throw 'attribute order and prefix ignored';var aa=a.getAttributeNodeNS('urn:attr','Name'),ba=b.getAttributeNodeNS('urn:attr','Name');if(!aa.isEqualNode(ba)||aa.isSameNode(ba))throw 'actual Attr equality';ba.value='changed';if(aa.isEqualNode(ba)||a.isEqualNode(b))throw 'actual attached Attr raw value';ba.value='value';if(!a.isEqualNode(b)||a.isEqualNode(x.createElementNS('urn:source','q:Root'))||a.isEqualNode(x.createElementNS('urn:other','p:Root')))throw 'Element prefix namespace';
var xmlns='http://www.w3.org/2000/xmlns/';a.setAttributeNS(xmlns,'xmlns:raw','v\ud800');b.setAttributeNS(xmlns,'xmlns:raw','v\ud800');var raw=a.getAttributeNodeNS(xmlns,'raw'),raw2=b.getAttributeNodeNS(xmlns,'raw');if(!a.isEqualNode(b)||!raw.isEqualNode(raw2))throw 'exact raw Attr';raw2.value='v\ufffd';if(a.isEqualNode(b)||raw.isEqualNode(raw2))throw 'raw Attr differs from replacement';
var text=x.createTextNode('v\ud800'),cd=x.createCDATASection('v\ud800'),comment=x.createComment('v\ud800');if(text.isEqualNode(cd)||text.isEqualNode(comment)||cd.isEqualNode(comment)||text.isEqualNode(x.createTextNode('v\ufffd')))throw 'interface and UTF16';var pi=x.createProcessingInstruction('target','value');if(!pi.isEqualNode(x.createProcessingInstruction('target','value'))||pi.isEqualNode(x.createProcessingInstruction('other','value')))throw 'PI target';var impl=x.implementation,dt=impl.createDocumentType('Root','pub','sys');if(!dt.isEqualNode(impl.createDocumentType('Root','pub','sys'))||dt.isEqualNode(impl.createDocumentType('Root','pub','else')))throw 'doctype tuple';if(new Document().isEqualNode(impl.createDocument(null,'')))throw 'Document versus XMLDocument';
"#);}
#[test]
fn node_equality_ordered_trees_clone_import_template_and_author_getters(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var a=document.createElement('section');a.appendChild(document.createTextNode('a'));a.appendChild(document.createComment('marker'));a.appendChild(document.createTextNode('b'));var b=a.cloneNode(true);if(!a.isEqualNode(b)||a.isSameNode(b)||a.isEqualNode(a.cloneNode(false)))throw 'deep actual children';b.appendChild(b.firstChild);if(a.isEqualNode(b))throw 'ordered children';b=a.cloneNode(true);var target=new Document(),copy=target.importNode(a,true);if(!a.isEqualNode(copy))throw 'ownerDocument ignored';Object.defineProperty(Element.prototype,'attributes',{configurable:true,get:function(){throw 'author attributes';}});Object.defineProperty(Node.prototype,'childNodes',{configurable:true,get:function(){throw 'author childNodes';}});if(!a.isEqualNode(b)||!a.isEqualNode(copy))throw 'native facts';var t=document.createElement('template'),u=document.createElement('template');t.innerHTML='<span>different content</span>';if(!t.isEqualNode(u)||t.content.isEqualNode(u.content))throw 'dedicated contents';
"#);}
#[test]
fn node_equality_blank_child_and_captured_origin(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,saved=w.Node.prototype.isEqualNode,child=w.document.body;if(!saved.call(child,document.createElement('body'))||!child.isSameNode(child)||child.isSameNode(document.body))throw 'real blank child';");p.set_location(&crate::navigation::address("https://other-equality.test/",&crate::navigation::Location::home()).unwrap());let before=(d.nodes.len(),p.state.retained,p.state.dom_commits);assert_eq!(p.console_eval(&mut d,&mut f,"saved.call(document,null);").errors,1);assert_eq!((d.nodes.len(),p.state.retained,p.state.dom_commits),before);assert_eq!(p.console_eval(&mut d,&mut f,"Node.prototype.isSameNode.call(child,child);").errors,1);}

#[test]
fn node_equality_no_native_slot_deep_tree_current_owners_and_observation(){let(mut d,mut f,mut p)=fixture();p.state.node_limit=d.nodes.len();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),a=owner.createElement('div'),tail=a;for(var i=0;i<350;i++){var next=owner.createElement('span');tail.appendChild(next);tail=next;}tail.appendChild(owner.createTextNode('raw\ud800'));var b=a.cloneNode(true),saved=a.firstChild,records=0,observer=new MutationObserver(function(items){records+=items.length;});observer.observe(a,{childList:true,subtree:true,characterData:true,attributes:true});if(!a.isEqualNode(b)||a.isSameNode(b)||!saved.isSameNode(a.firstChild))throw 'deep no-slot identities';var moved=new Document().adoptNode(b);if(moved!==b||!a.isEqualNode(b))throw 'owner and connection ignored';var bt=b;for(var i=0;i<350;i++)bt=bt.firstChild;bt.firstChild.data='changed';if(a.isEqualNode(b)||records!==0||a.firstChild!==saved)throw 'current data without observation mutation';observer.disconnect();
"#);}
